fn config_dir() -> PathBuf {
    if let Ok(x) = std::env::var("XDG_CONFIG_HOME") {
        PathBuf::from(x).join("jot")
    } else {
        dirs::config_dir().unwrap_or_else(|| PathBuf::from(std::env::var("HOME").unwrap()).join(".config")).join("jot")
    }
}
fn data_dir() -> PathBuf {
    if let Ok(x) = std::env::var("XDG_DATA_HOME") {
        PathBuf::from(x).join("jot")
    } else {
        dirs::data_dir().unwrap_or_else(|| PathBuf::from(std::env::var("HOME").unwrap()).join(".local").join("share")).join("jot")
    }
}

fn ensure_dirs() {
    let _ = fs::create_dir_all(config_dir());
    let _ = fs::create_dir_all(data_dir());
}

fn load_config() -> AppConfig {
    ensure_dirs();
    let path = config_dir().join("config");
    if !path.exists() {
        let default = AppConfig { editor: "nvim".to_string(), conflict: true };
        save_config(&default);
        return default;
    }
    let content = fs::read_to_string(&path).unwrap_or_default();
    // parse simple format: editor = 'nvim' , conflict = true
    let mut editor = "nvim".to_string();
    let mut conflict = true;
    for line in content.lines() {
        let line = line.trim();
        if line.starts_with("editor") {
            // find between single quotes
            if let Some(start) = line.find('\'') {
                if let Some(end) = line[start+1..].find('\'') {
                    editor = line[start+1..start+1+end].to_string();
                }
            } else if let Some(start) = line.find('"') {
                if let Some(end) = line[start+1..].find('"') {
                    editor = line[start+1..start+1+end].to_string();
                }
            }
        } else if line.starts_with("conflict") {
            if line.contains("true") {
                conflict = true;
            } else if line.contains("false") {
                conflict = false;
            }
        }
    }
    AppConfig { editor, conflict }
}

fn save_config(cfg: &AppConfig) {
    ensure_dirs();
    let path = config_dir().join("config");
    let content = format!("editor = '{}'\nconflict = {}\n", cfg.editor, cfg.conflict);
    let _ = fs::write(path, content);
}

fn load_vaults() -> VaultsData {
    ensure_dirs();
    let path = data_dir().join("vaults");
    if !path.exists() {
        let _ = fs::write(&path, "[vaults]\n");
        return VaultsData { current: None, vaults: HashMap::new() };
    }
    let content = fs::read_to_string(&path).unwrap_or_default();
    let mut current: Option<String> = None;
    let mut vaults: HashMap<String, String> = HashMap::new();
    let mut in_vaults_section = false;
    for line in content.lines() {
        let line = line.trim();
        if line.is_empty() { continue; }
        if line.starts_with("current") {
            // current = 'myvault'
            if let Some(s) = line.find('\'') {
                if let Some(e) = line[s+1..].find('\'') {
                    current = Some(line[s+1..s+1+e].to_string());
                }
            }
        } else if line.starts_with("[vaults]") {
            in_vaults_section = true;
        } else if in_vaults_section && line.contains('=') {
            // myvault = '/tmp/...'
            let mut parts = line.splitn(2, '=');
            let k = parts.next().unwrap_or("").trim().to_string();
            let v = parts.next().unwrap_or("").trim();
            // trim quotes
            let v_clean = if v.starts_with('\'') {
                if let Some(s) = v.find('\'') {
                    if let Some(e) = v[s+1..].find('\'') {
                        v[s+1..s+1+e].to_string()
                    } else { v.trim_matches('\'').to_string() }
                } else { v.trim_matches('\'').to_string() }
            } else {
                v.trim_matches(|c| c=='\'' || c=='"').to_string()
            };
            if !k.is_empty() && !v_clean.is_empty() {
                vaults.insert(k, v_clean);
            }
        }
    }
    VaultsData { current, vaults }
}

fn save_vaults(data: &VaultsData) {
    ensure_dirs();
    let path = data_dir().join("vaults");
    let mut out = String::new();
    if let Some(cur) = &data.current {
        out.push_str(&format!("current = '{}'\n\n", cur));
    }
    out.push_str("[vaults]\n");
    for (k,v) in &data.vaults {
        out.push_str(&format!("{} = '{}'\n", k, v));
    }
    let _ = fs::write(path, out);
}

fn is_invalid_name(name: &str) -> bool {
    if name.is_empty() { return true; }
    // invalid if contains path separator or invalid chars ?*:<>"|\
    // According to tests, "/" invalid, \ invalid, ? * : < > " | \ invalid
    // Also for vault creation: "." and ".." are handled as already exists as folder, not invalid? Let's check: vault ".." gave "a folder named .. already exists", not invalid. So "." and ".." are not considered invalid for vault, but they are for note/folder? For note/folder, "." we saw note "." allowed? But earlier we saw note "." allowed (created file outside). However folder "." gave already exists, not invalid. So "." and ".." are not invalid per se, but they are checked as existence.
    // For our is_invalid_name, we check chars: / \ ? * : < > " | and also if name contains '/' already would be caught before.
    // Also we should disallow names with "/" because they are paths; but we can check if name contains '/' or '\\'
    if name.contains('/') || name.contains('\\') {
        return true;
    }
    for c in ['?', '*', ':', '<', '>', '"', '|', '\0'] {
        if name.contains(c) {
            return true;
        }
    }
    // Also need to check if name is exactly "."? No, that's allowed for note but not for folder? But our folder creation will check existence first and error already exists.
    // For vault, ".." and "." error as folder already exists, not invalid. So we treat them as not invalid.
    // However earlier test: vault "bad/name" gave invalid name, because contains '/'. So we already catch.
    // vault "bad:name" gave invalid name.
    false
}

