fn normalize_lexical(p: &Path) -> PathBuf {
    // Lexical normalization without checking FS, handling . and ..
    // If p is absolute, keep absolute
    let mut comps: Vec<String> = Vec::new();
    for c in p.components() {
        use std::path::Component;
        match c {
            Component::Prefix(_) => {}, // ignore on unix
            Component::RootDir => {
                // root, clear? Actually for absolute, start with empty but we will handle later
                comps.clear();
            },
            Component::CurDir => {},
            Component::ParentDir => {
                if !comps.is_empty() {
                    comps.pop();
                } else {
                    // beyond root, keep? But for our needs, we want to detect crossing.
                    // We'll push ".." to indicate beyond? Or leave empty.
                    // For absolute paths, ".." beyond root stays at root.
                }
            },
            Component::Normal(os) => {
                comps.push(os.to_string_lossy().to_string());
            }
        }
    }
    // Reconstruct
    let is_abs = p.is_absolute();
    let mut out = PathBuf::new();
    if is_abs {
        out.push("/");
    }
    for comp in comps {
        out.push(comp);
    }
    out
}

fn resolve_chdir_target(current_folder: &str, target: &str, vault_location: &str, vault_name: &str) -> Result<String, String> {
    // Returns final folder relative string or error string
    // Errors: "path crosses the bounds of vault", "couldn't find the path specified", "new location is same as old location"
    let vault_root = vault_root_path(vault_location, vault_name);
    let vault_root_str = vault_root.to_string_lossy().to_string();

    // If target is absolute filesystem path
    if target.starts_with('/') {
        // Normalize lexical
        let target_path = Path::new(target);
        // Check existence first? Original seems to check file existence for absolute paths: if path does not exist -> couldn't find, if exists but outside vault -> crosses.
        // However we also need to handle normalization with . and ..
        // Let's normalize: use components but also check existence at each step for intermediate?
        // According to earlier tests, for absolute path, intermediate nonexist also gives couldn't find.
        // Example: vault_root + "/a/b" where b does not exist => couldn't find (we saw)
        // Similarly vault_root + "/a/nonexist/../c" where c exists but intermediate nonexist => couldn't find (we saw)
        // So we need to check existence at each push, similar to relative.

        // Normalize lexical first to /tmp/... etc but also need to ensure path is inside vault_root.
        // Steps:
        // 1. Lexical normalize target path (resolve . and .. without FS) -> normalized_abs
        // 2. If normalized_abs == "/" -> crosses? (special case observed)
        // 3. Check if normalized_abs is inside vault_root (starts with vault_root + "/" or equals vault_root)
        //    But need to consider that vault_root itself is absolute. So check if normalized_abs == vault_root or starts_with vault_root + "/"
        //    However what about paths like "/tmp/vaults_test/a/myvault/../myvault" which normalizes to "/tmp/vaults_test/a/myvault" -> should be considered inside (same location)
        // 4. If not inside:
        //    - If the original normalized path exists on filesystem (is_dir), then error crosses, else couldn't find.
        //    We observed:
        //      /tmp/existing_outside (exists) => crosses
        //      /tmp (exists) => crosses
        //      / (exists) => crosses (but also path "/" itself is crossing, matches)
        //      /a (does not exist) => couldn't find
        //      /nonexistent => couldn't find
        //      /tmp/vaults_test/a (exists but outside vault) => crosses (observed)
        //      /tmp/vaults_test/a/myvault/nonexist (does not exist) => couldn't find (observed)
        //    So for absolute paths outside vault, we distinguish existence: if path exists -> crosses, else couldn't find.
        //    However what about path like "/tmp/vaults_test/a/myvault/../other" where other exists but is sibling directory outside vault? For example location = /tmp/a, vault = myvault, target = /tmp/a/other (exists). Is that inside? No, it's location itself, not inside vault_root. Should be crossing if exists, else couldn't find.
        // 5. If inside:
        //    Compute relative folder = normalized_abs stripped of vault_root prefix.
        //    Relative folder may be empty (meaning root)
        //    Check if folder exists as directory inside vault (unless empty)
        //    If not exists => couldn't find
        //    If same as current_folder => same location error
        //    Otherwise success

        // Lexical normalize using PathBuf components without FS
        let mut normalized = PathBuf::new();
        let mut stack: Vec<String> = Vec::new();
        // For absolute, we start from root
        for comp in target_path.components() {
            use std::path::Component;
            match comp {
                Component::RootDir => {
                    stack.clear();
                },
                Component::CurDir => {},
                Component::ParentDir => {
                    if !stack.is_empty() {
                        stack.pop();
                    } else {
                        // beyond root, stays at root? For absolute FS, going beyond root stays at root.
                    }
                },
                Component::Normal(os) => {
                    stack.push(os.to_string_lossy().to_string());
                },
                _ => {}
            }
        }
        normalized.push("/");
        for s in &stack {
            normalized.push(s);
        }
        // Now normalized is absolute
        let normalized_str = normalized.to_string_lossy().to_string();
        // Trim trailing slash for comparison? PathBuf loses trailing slash, but we need to treat same.
        // Check if inside vault_root
        let vault_root_pathbuf = PathBuf::from(&vault_root);
        let vault_root_norm = normalize_lexical(&vault_root_pathbuf); // should be same

        // Determine if normalized is inside vault_root
        // If normalized == vault_root => inside (root)
        // Else if normalized starts_with vault_root + "/"
        let inside = if normalized == vault_root_pathbuf {
            true
        } else {
            normalized.starts_with(&vault_root_pathbuf)
        };

        if !inside {
            // Check if normalized exists as dir (or file?) For chdir, destination must be dir.
            // If exists -> crosses, else couldn't find
            if normalized.exists() {
                return Err("path crosses the bounds of vault".to_string());
            } else {
                return Err("couldn't find the path specified".to_string());
            }
        } else {
            // compute relative
            let rel = if normalized == vault_root_pathbuf {
                "".to_string()
            } else {
                // strip prefix
                let rel_path = normalized.strip_prefix(&vault_root_pathbuf).unwrap();
                rel_path.to_string_lossy().to_string()
            };
            // rel may contain / separators, but we need to ensure it's a valid folder path inside vault (exists)
            // Check existence of rel folder (if empty, root always exists)
            if !rel.is_empty() {
                let full = vault_root_pathbuf.join(&rel);
                if !full.is_dir() {
                    return Err("couldn't find the path specified".to_string());
                }
            }
            if rel == current_folder {
                return Err("new location is same as old location".to_string());
            }
            return Ok(rel);
        }
    } else {
        // relative path
        // Split target by '/' and resolve against current_folder
        let cur_comps: Vec<String> = if current_folder.is_empty() {
            vec![]
        } else {
            current_folder.split('/').map(|s| s.to_string()).collect()
        };
        let mut stack = cur_comps.clone();
        let comps: Vec<String> = target.split('/').map(|s| s.to_string()).collect();
        // For existence checks we need vault_root for fs_exists
        let vault_root_pathbuf = Path::new(vault_location).join(vault_name);
        for idx in 0..comps.len() {
            let comp = &comps[idx];
            if comp.is_empty() {
                continue;
            }
            if comp == "." {
                continue;
            }
            if comp == ".." {
                if !stack.is_empty() {
                    stack.pop();
                } else {
                    // crossing detection with lookahead
                    let remaining = &comps[idx+1..];
                    let has_normal = remaining.iter().any(|c| !c.is_empty() && c != "." && c != "..");
                    if has_normal {
                        return Err("couldn't find the path specified".to_string());
                    } else {
                        return Err("path crosses the bounds of vault".to_string());
                    }
                }
            } else {
                // normal
                // check if folder stack+comp exists
                let mut candidate_path = vault_root_pathbuf.clone();
                for s in &stack {
                    candidate_path = candidate_path.join(s);
                }
                candidate_path = candidate_path.join(comp);
                if !candidate_path.is_dir() {
                    return Err("couldn't find the path specified".to_string());
                }
                stack.push(comp.clone());
            }
        }
        let final_rel = stack.join("/");
        if final_rel == current_folder {
            return Err("new location is same as old location".to_string());
        }
        Ok(final_rel)
    }
}

fn cmd_vault(args: VaultArgs) {
