fn cmd_list(args: ListArgs) {
    let cur_info = current_folder_full_path();
    if cur_info.is_none() {
        return;
    }
    let (vname, _vloc, folder, full_current) = cur_info.unwrap();

    // header
    let header = if folder.is_empty() {
        vname.clone()
    } else {
        format!("{} > {}", vname, folder)
    };
    println!("{}", header);

    // Determine filter
    let filter_raw = args.item_type.as_deref();
    // filter values: note, nt, folder, fd
    // If invalid value, clap should error? In original, list invalid gave clap error: "error: \"invalid\" isn't a valid value for '<item type>' [possible values: note, nt, folder, fd]"
    // Our clap would not automatically validate since we use Option<String> without possible values. So we need to implement validation manually to match original clap error message.
    // Let's do manual check.

    let mut filter_kind: Option<String> = None; // "note" or "folder" or None
    if let Some(t) = filter_raw {
        match t {
            "note" | "nt" => filter_kind = Some("note".to_string()),
            "folder" | "fd" => filter_kind = Some("folder".to_string()),
            _ => {
                // clap error
                eprintln!("error: \"{}\" isn't a valid value for '<item type>'", t);
                eprintln!("\t[possible values: note, nt, folder, fd]");
                eprintln!();
                eprintln!("For more information try --help");
                // Note: original exit code 2? But for list invalid, they had exit 2 and printed to stderr? Actually earlier we saw list invalid stdout empty, stderr had that error. So we should print to stderr and exit 2.
                // We'll use eprintln for error and exit.
                std::process::exit(2);
            }
        }
    }

    if filter_kind.is_none() {
        // recursive listing, excluding .jot
        // Build tree recursively
        // We need function that lists entries at path in filesystem order (read_dir order)
        // And recursively descends into folders

        // For simplicity, implement function that returns list of (name, is_note, path) for a directory, in read_dir order, excluding .jot at top? Actually for no-filter, we exclude .jot entirely from tree, including at root and any level? .jot only exists at vault root .jot folder, so excluding it at root is sufficient. But also if there is folder named .jot inside subfolders? Unlikely, but we should exclude any .jot folder? Original folder filter included .jot, so for no-filter they excluded .jot. So for no-filter we skip any entry where file_name == ".jot".

        // Also need to distinguish notes vs folders: notes are files with .md extension, but display without .md plus colored
        // Folders are directories

        // Recursive printing: we need to print tree with proper prefixes.

        // Collect immediate children at root, but then for each folder child, we need to print it and then its children indented.

        // Implementation approach: create a Vec of entries at current level in order of read_dir.

        fn collect_entries(path: &Path) -> Vec<(String, bool, PathBuf)> {
            // bool is_note
            let mut entries = Vec::new();
            if let Ok(read_dir) = fs::read_dir(path) {
                for entry in read_dir {
                    if let Ok(entry) = entry {
                        let ft = entry.file_type();
                        if ft.is_err() { continue; }
                        let ft = ft.unwrap();
                        let fname_os = entry.file_name();
                        let fname = fname_os.to_string_lossy().to_string();
                        if fname == ".jot" {
                            continue; // skip for no-filter
                        }
                        let p = entry.path();
                        if ft.is_dir() {
                            entries.push((fname, false, p));
                        } else if ft.is_file() {
                            // check if .md
                            if p.extension().map_or(false, |ext| ext == "md") {
                                // get file_stem
                                if let Some(stem) = p.file_stem() {
                                    let stem_str = stem.to_string_lossy().to_string();
                                    entries.push((stem_str, true, p));
                                }
                            }
                        }
                    }
                }
            }
            entries
        }

        fn print_recursive(path: &Path, prefix: String, is_last_stack: Vec<bool>) {
            let entries = collect_entries(path);
            let len = entries.len();
            for (i, (name, is_note, child_path)) in entries.into_iter().enumerate() {
                let is_last = i == len - 1;
                // build line prefix
                let mut line_prefix = String::new();
                for &is_last_parent in &is_last_stack {
                    if is_last_parent {
                        line_prefix.push_str("    ");
                    } else {
                        line_prefix.push_str("│   ");
                    }
                }
                let branch = if is_last { "└── " } else { "├── " };
                let display_name = if is_note {
                    name.blue().to_string()
                } else {
                    name.clone()
                };
                println!("{}{}{}", line_prefix, branch, display_name);
                if !is_note {
                    // folder, recurse
                    let mut new_stack = is_last_stack.clone();
                    new_stack.push(is_last);
                    print_recursive(&child_path, line_prefix, new_stack);
                }
            }
        }

        // Define nested functions inside cmd_list via closure? Rust doesn't allow nested fn capturing variables but we defined inner functions that don't capture.
        // However collect_entries needs to be in scope. We'll reimplement inline.

        // We'll call print_recursive with full_current
        // But our inner functions defined above inside this branch need to be defined outside? Let's redefine here as inline logic using recursion via inner function that captures nothing but calls itself.

        // To avoid complexity, we will implement iterative recursion manually outside.

        // Actually we already defined collect_entries and print_recursive inside, but they are not accessible outside? They are defined inside if block, so okay.

        // Let's call
        print_recursive(&full_current, "".to_string(), vec![]);
    } else if filter_kind.as_deref() == Some("note") {
        // immediate notes only
        if let Ok(read_dir) = fs::read_dir(&full_current) {
            let mut notes = Vec::new();
            for entry in read_dir {
                if let Ok(entry) = entry {
                    let ft = match entry.file_type() {
                        Ok(ft) => ft,
                        Err(_) => continue,
                    };
                    if ft.is_file() {
                        let p = entry.path();
                        if p.extension().map_or(false, |ext| ext == "md") {
                            if let Some(stem) = p.file_stem() {
                                notes.push(stem.to_string_lossy().to_string());
                            }
                        }
                    }
                }
            }
            let len = notes.len();
            for (i, name) in notes.iter().enumerate() {
                let branch = if i == len - 1 { "└── " } else { "├── " };
                println!("{}{}", branch, name.blue());
            }
        }
    } else if filter_kind.as_deref() == Some("folder") {
        // immediate folders only, include .jot
        if let Ok(read_dir) = fs::read_dir(&full_current) {
            let mut folders = Vec::new();
            for entry in read_dir {
                if let Ok(entry) = entry {
                    let ft = match entry.file_type() {
                        Ok(ft) => ft,
                        Err(_) => continue,
                    };
                    if ft.is_dir() {
                        let fname = entry.file_name().to_string_lossy().to_string();
                        folders.push(fname);
                    }
                }
            }
            // Note: order is filesystem order, not sorted. read_dir order matches original.
            let len = folders.len();
            for (i, name) in folders.iter().enumerate() {
                let branch = if i == len - 1 { "└── " } else { "├── " };
                println!("{}{}", branch, name);
            }
        }
    }
}

