fn cmd_config(args: ConfigArgs) {
    let cfg = load_config();
    if args.config_type.is_none() {
        // open config in editor
        // Spawn editor with config file path
        let config_path = config_dir().join("config");
        let mut cmd = std::process::Command::new(&cfg.editor);
        cmd.arg(&config_path);
        match cmd.status() {
            Ok(_) => {},
            Err(e) => {
                if e.kind() == std::io::ErrorKind::NotFound {
                    error_print("editor not found");
                } else {
                    error_print(&format!("undefined error: {} (os error {})", e, e.raw_os_error().unwrap_or(0)));
                }
            }
        }
        return;
    }
    let ctype = args.config_type.clone().unwrap().to_lowercase();
    let cvalue = args.config_value;

    match ctype.as_str() {
        "editor" => {
            if let Some(val) = cvalue {
                let new_cfg = AppConfig { editor: val.clone(), conflict: cfg.conflict };
                save_config(&new_cfg);
                println!("set {} to {}", "editor".blue(), val.blue());
            } else {
                println!("editor: {}", cfg.editor.blue());
            }
        },
        "conflict" => {
            if let Some(val) = cvalue {
                // parse bool, unwrap will panic on invalid
                let bool_val = parse_bool(&val);
                let new_cfg = AppConfig { editor: cfg.editor, conflict: bool_val };
                save_config(&new_cfg);
                println!("set {} to {}", "conflict".blue(), format!("{}", bool_val).blue());
            } else {
                println!("conflict: {}", format!("{}", cfg.conflict).blue());
            }
        },
        _ => {
            eprintln!("error: \"{}\" isn't a valid value for '<config type>'", args.config_type.unwrap());
            eprintln!("\t[possible values: editor, conflict]");
            eprintln!();
            eprintln!("For more information try --help");
            std::process::exit(2);
        }
    }
}

