fn cmd_enter(args: &[String]) {
    if args.is_empty() {
        eprintln!("error: The following required arguments were not provided:");
        eprintln!("    <vault name>");
        eprintln!();
        eprintln!("USAGE:");
        eprintln!("    executable enter <vault name>");
        eprintln!();
        eprintln!("For more information try --help");
        std::process::exit(2);
    }
    if args[0] == "-h" || args[0] == "--help" {
        help_enter();
        return;
    }
    if args.len() > 1 {
        eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context", args[1]);
        eprintln!();
        eprintln!("USAGE:");
        eprintln!("    executable enter <vault name>");
        eprintln!();
        eprintln!("For more information try --help");
        std::process::exit(2);
    }
    let vault_name = args[0].clone();
    let mut vaults = load_vaults();
    if !vaults.vaults.contains_key(&vault_name) {
        error_print(&format!("vault {} doesn't exist", vault_name));
        return;
    }
    if let Some(cur) = &vaults.current {
        if cur == &vault_name {
            error_print(&format!("already in vault {}", vault_name));
            return;
        }
    }
    vaults.current = Some(vault_name.clone());
    save_vaults(&vaults);
    println!("entered {}", colored_name(&vault_name));
}

