fn cmd_list(args: &[String]) {
    if !args.is_empty() && (args[0] == "-h" || args[0] == "--help") {
        help_list();
        return;
    }
    let filter_opt = if args.is_empty() { None } else { Some(args[0].clone()) };
    if let Some(ref t) = filter_opt {
        match t.as_str() {
            "note" | "nt" | "folder" | "fd" => {},
            _ => {
                eprintln!("error: \"{}\" isn't a valid value for '<item type>'", t);
                eprintln!("\t[possible values: note, nt, folder, fd]");
                eprintln!();
                eprintln!("For more information try --help");
                std::process::exit(2);
            }
        }
    }
    let cur_info = ensure_inside_vault();
    if cur_info.is_none() { return; }
    let (vname, _vloc, folder, full_current) = cur_info.unwrap();
    let header = if folder.is_empty() { vname.clone() } else { format!("{} > {}", vname, folder) };
    println!("{}", header);

    if filter_opt.is_none() {
        fn collect_entries(path: &Path) -> Vec<(String, bool, PathBuf)> {
            let mut entries = Vec::new();
            if let Ok(read_dir) = fs::read_dir(path) {
                for entry in read_dir {
                    if let Ok(entry) = entry {
                        let ft = match entry.file_type() {
                            Ok(ft) => ft,
                            Err(_) => continue,
                        };
                        let fname = entry.file_name().to_string_lossy().to_string();
                        if fname == ".jot" { continue; }
                        let p = entry.path();
                        if ft.is_dir() {
                            entries.push((fname, false, p));
                        } else if ft.is_file() {
                            if p.extension().map_or(false, |ext| ext == "md") {
                                if let Some(stem) = p.file_stem() {
                                    entries.push((stem.to_string_lossy().to_string(), true, p));
                                }
                            }
                        }
                    }
                }
            }
            entries
        }
        fn print_recursive(path: &Path, is_last_stack: Vec<bool>) {
            let entries = collect_entries(path);
            let len = entries.len();
            for (i, (name, is_note, child_path)) in entries.into_iter().enumerate() {
                let is_last = i == len - 1;
                let mut line_prefix = String::new();
                for &is_last_parent in &is_last_stack {
                    if is_last_parent {
                        line_prefix.push_str("    ");
                    } else {
                        line_prefix.push_str("│   ");
                    }
                }
                let branch = if is_last { "└── " } else { "├── " };
                let display_name = if is_note { name.blue().to_string() } else { name.clone() };
                println!("{}{}{}", line_prefix, branch, display_name);
                if !is_note {
                    let mut new_stack = is_last_stack.clone();
                    new_stack.push(is_last);
                    print_recursive(&child_path, new_stack);
                }
            }
        }
        print_recursive(&full_current, vec![]);
    } else {
        let filter = filter_opt.unwrap();
        match filter.as_str() {
            "note" | "nt" => {
                if let Ok(read_dir) = fs::read_dir(&full_current) {
                    let mut notes = Vec::new();
                    for entry in read_dir {
                        if let Ok(entry) = entry {
                            let ft = match entry.file_type() {
                                Ok(ft) => ft,
                                Err(_) => continue,
                            };
                            if ft.is_file() {
                                let p = entry.path();
                                if p.extension().map_or(false, |ext| ext == "md") {
                                    if let Some(stem) = p.file_stem() {
                                        notes.push(stem.to_string_lossy().to_string());
                                    }
                                }
                            }
                        }
                    }
                    let len = notes.len();
                    for (i, name) in notes.iter().enumerate() {
                        let branch = if i == len - 1 { "└── " } else { "├── " };
                        println!("{}{}", branch, name.blue());
                    }
                }
            },
            "folder" | "fd" => {
                if let Ok(read_dir) = fs::read_dir(&full_current) {
                    let mut folders = Vec::new();
                    for entry in read_dir {
                        if let Ok(entry) = entry {
                            let ft = match entry.file_type() {
                                Ok(ft) => ft,
                                Err(_) => continue,
                            };
                            if ft.is_dir() {
                                folders.push(entry.file_name().to_string_lossy().to_string());
                            }
                        }
                    }
                    let len = folders.len();
                    for (i, name) in folders.iter().enumerate() {
                        let branch = if i == len - 1 { "└── " } else { "├── " };
                        println!("{}{}", branch, name);
                    }
                }
            },
            _ => {}
        }
    }
}

fn cmd_remove(args: &[String]) {
    if args.is_empty() {
        eprintln!("error: The following required arguments were not provided:");
        eprintln!("    <item type>");
        eprintln!("    <name>");
        eprintln!();
        eprintln!("USAGE:");
        eprintln!("    executable remove <item type> <name>");
        eprintln!();
        eprintln!("For more information try --help");
        std::process::exit(2);
    }
    if args.len() == 1 {
        if args[0] == "-h" || args[0] == "--help" {
            help_remove();
            return;
        }
        eprintln!("error: The following required arguments were not provided:");
        eprintln!("    <name>");
        eprintln!();
        eprintln!("USAGE:");
        eprintln!("    executable remove <item type> <name>");
        eprintln!();
        eprintln!("For more information try --help");
        std::process::exit(2);
    }
    if args[0] == "-h" || args[0] == "--help" {
        help_remove();
        return;
    }
    if args.len() > 2 {
        eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context", args[2]);
        eprintln!();
        eprintln!("USAGE:");
        eprintln!("    executable remove <item type> <name>");
        eprintln!();
        eprintln!("For more information try --help");
        std::process::exit(2);
    }
    let itype = args[0].to_lowercase();
    let name = args[1].clone();
    match itype.as_str() {
        "vault" | "vl" => {
            let mut vaults = load_vaults();
            if !vaults.vaults.contains_key(&name) {
                error_print(&format!("vault {} doesn't exist", name));
                return;
            }
            let loc = vaults.vaults.get(&name).unwrap().clone();
            let full_path = vault_full_path(&loc, &name);
            if full_path.exists() {
                let _ = fs::remove_dir_all(&full_path);
            }
            vaults.vaults.remove(&name);
            if let Some(cur) = &vaults.current {
                if cur == &name {
                    vaults.current = None;
                }
            }
            save_vaults(&vaults);
            println!("vault {} removed", colored_name(&name));
        },
        "note" | "nt" => {
            let cur_info = ensure_inside_vault();
            if cur_info.is_none() { return; }
            let (_vname, _vloc, _folder, full_current) = cur_info.unwrap();
            let note_path = full_current.join(&name).with_extension("md");
            if !note_path.exists() || !note_path.is_file() {
                error_print(&format!("note {} not found", name));
                return;
            }
            let _ = fs::remove_file(&note_path);
            println!("note {} removed", colored_name(&name));
        },
        "folder" | "fd" => {
            let cur_info = ensure_inside_vault();
            if cur_info.is_none() { return; }
            let (vname, vloc, current_folder, full_current) = cur_info.unwrap();
            let folder_path = full_current.join(&name);
            if !folder_path.exists() || !folder_path.is_dir() {
                error_print(&format!("folder {} not found", name));
                return;
            }
            let removed_rel = if current_folder.is_empty() { name.clone() } else { format!("{}/{}", current_folder, name) };
            let _ = fs::remove_dir_all(&folder_path);
            if current_folder == removed_rel || current_folder.starts_with(&format!("{}/", removed_rel)) {
                write_data_file(&vloc, &vname, "");
            }
            println!("folder {} removed", colored_name(&name));
        },
        _ => {
            eprintln!("error: \"{}\" isn't a valid value for '<item type>'", args[0]);
            eprintln!("\t[possible values: note, nt, folder, fd, vault, vl]");
            eprintln!();
            eprintln!("For more information try --help");
            std::process::exit(2);
        }
    }
}

