fn cmd_config(args: &[String]) {
    if !args.is_empty() && (args[0] == "-h" || args[0] == "--help") {
        help_config();
        return;
    }
    let cfg = load_config();
    if args.is_empty() {
        let config_path = config_dir().join("config");
        let mut cmd = std::process::Command::new(&cfg.editor);
        cmd.arg(&config_path);
        match cmd.status() {
            Ok(_) => {},
            Err(e) => {
                if e.kind() == std::io::ErrorKind::NotFound {
                    error_print("editor not found");
                } else {
                    error_print(&format!("undefined error: {} (os error {})", e, e.raw_os_error().unwrap_or(0)));
                }
            }
        }
        return;
    }
    if args.len() == 1 {
        let ctype = args[0].to_lowercase();
        match ctype.as_str() {
            "editor" => {
                println!("editor: {}", cfg.editor.blue());
            },
            "conflict" => {
                println!("conflict: {}", format!("{}", cfg.conflict).blue());
            },
            _ => {
                eprintln!("error: \"{}\" isn't a valid value for '<config type>'", args[0]);
                eprintln!("\t[possible values: editor, conflict]");
                eprintln!();
                eprintln!("For more information try --help");
                std::process::exit(2);
            }
        }
        return;
    }
    if args.len() == 2 {
        let ctype = args[0].to_lowercase();
        let cvalue = args[1].clone();
        match ctype.as_str() {
            "editor" => {
                let new_cfg = AppConfig { editor: cvalue.clone(), conflict: cfg.conflict };
                save_config(&new_cfg);
                println!("set {} to {}", "editor".blue(), cvalue.blue());
            },
            "conflict" => {
                let bool_val = parse_bool(&cvalue);
                let new_cfg = AppConfig { editor: cfg.editor, conflict: bool_val };
