        eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context", args[3]);
        eprintln!();
        eprintln!("USAGE:");
        eprintln!("    executable move <item type> <name> <new location>");
        eprintln!();
        eprintln!("For more information try --help");
        std::process::exit(2);
    }
    let itype = args[0].to_lowercase();
    let name = args[1].clone();
    let new_location = args[2].clone();
    match itype.as_str() {
        "vault" | "vl" => {
            let mut vaults = load_vaults();
            if !vaults.vaults.contains_key(&name) {
                error_print(&format!("vault {} doesn't exist", name));
                return;
            }
            if !Path::new(&new_location).is_absolute() {
                error_print("specified path isn't absolute");
                return;
            }
            if !Path::new(&new_location).exists() {
                error_print(&format!("no such file or directory (os error 2)"));
                return;
            }
            let old_loc = vaults.vaults.get(&name).unwrap().clone();
            if old_loc == new_location {
                error_print("new location is same as old location");
                return;
            }
            let old_full = vault_full_path(&old_loc, &name);
            let new_full = vault_full_path(&new_location, &name);
            if new_full.exists() {
                error_print(&format!("a folder named {} already exists in this location", name));
                return;
            }
            if let Err(_e) = fs::rename(&old_full, &new_full) {
                error_print(&format!("no such file or directory (os error 2)"));
                return;
            }
            let data_path = new_full.join(".jot").join("data");
            if data_path.exists() {
                if let Ok(content) = fs::read_to_string(&data_path) {
                    let mut new_content = String::new();
                    for line in content.lines() {
                        if line.trim_start().starts_with("location") {
                            new_content.push_str(&format!("location = '{}'\n", new_location));
                        } else {
                            new_content.push_str(line);
                            new_content.push('\n');
                        }
                    }
                    let _ = fs::write(&data_path, new_content);
                }
            }
            vaults.vaults.insert(name.clone(), new_location);
            save_vaults(&vaults);
            println!("vault {} moved", colored_name(&name));
        },
        "note" | "nt" | "folder" | "fd" => {
            let is_note = matches!(itype.as_str(), "note" | "nt");
            let cur_info = ensure_inside_vault();
            if cur_info.is_none() { return; }
            let (vname, vloc, current_folder, full_current) = cur_info.unwrap();
            let vault_root = vault_root_path(&vloc, &vname);
            let source_path = if is_note {
                full_current.join(&name).with_extension("md")
            } else {
                full_current.join(&name)
            };
            if !source_path.exists() {
                if is_note {
                    error_print(&format!("note {} not found", name));
                } else {
                    error_print(&format!("folder {} not found", name));
                }
                return;
            }
            if is_note && !source_path.is_file() {
                error_print(&format!("note {} not found", name));
                return;
            }
            if !is_note && !source_path.is_dir() {
                error_print(&format!("folder {} not found", name));
                return;
            }
            let dest_folder_rel = match resolve_chdir_target(&current_folder, &new_location, &vloc, &vname) {
                Ok(rel) => rel,
                Err(msg) => {
                    error_print(&msg);
                    return;
                }
            };
            let dest_full = if dest_folder_rel.is_empty() { vault_root.clone() } else { vault_root.join(&dest_folder_rel) };
            let final_dest = if is_note {
                dest_full.join(&name).with_extension("md")
            } else {
                dest_full.join(&name)
            };
            if !is_note && final_dest.starts_with(&source_path) {
                let _ = fs::remove_dir_all(&source_path);
                let source_rel = if current_folder.is_empty() { name.clone() } else { format!("{}/{}", current_folder, name) };
                if current_folder == source_rel || current_folder.starts_with(&format!("{}/", source_rel)) {
                    write_data_file(&vloc, &vname, "");
                }
                println!("folder {} moved", colored_name(&name));
                return;
            }
            if final_dest.exists() {
                if is_note {
                    error_print(&format!("a note named {} already exists in this location", name));
                } else {
                    error_print(&format!("a folder named {} already exists in this location", name));
                }
                return;
            }
            if is_note {
                if let Err(e) = fs::rename(&source_path, &final_dest) {
                    error_print(&format!("{} (os error {})", e, e.raw_os_error().unwrap_or(0)));
                    return;
                }
                println!("note {} moved", colored_name(&name));
            } else {
                let source_rel = if current_folder.is_empty() { name.clone() } else { format!("{}/{}", current_folder, name) };
                if let Err(e) = fs::rename(&source_path, &final_dest) {
                    error_print(&format!("{} (os error {})", e, e.raw_os_error().unwrap_or(0)));
                    return;
                }
                if current_folder == source_rel || current_folder.starts_with(&format!("{}/", source_rel)) {
                    write_data_file(&vloc, &vname, "");
                }
                println!("folder {} moved", colored_name(&name));
            }
        },
        _ => {
            eprintln!("error: \"{}\" isn't a valid value for '<item type>'", args[0]);
            eprintln!("\t[possible values: note, nt, folder, fd, vault, vl]");
            eprintln!();
            eprintln!("For more information try --help");
            std::process::exit(2);
        }
    }
}

fn cmd_vmove(args: &[String]) {
    if args.is_empty() {
        eprintln!("error: The following required arguments were not provided:");
        eprintln!("    <item type>");
        eprintln!("    <name>");
        eprintln!("    <vault name>");
        eprintln!();
        eprintln!("USAGE:");
        eprintln!("    executable vmove <item type> <name> <vault name>");
        eprintln!();
        eprintln!("For more information try --help");
        std::process::exit(2);
    }
    if args.len() == 1 {
        eprintln!("error: The following required arguments were not provided:");
        eprintln!("    <name>");
        eprintln!("    <vault name>");
        eprintln!();
        eprintln!("USAGE:");
        eprintln!("    executable vmove <item type> <name> <vault name>");
        eprintln!();
        eprintln!("For more information try --help");
        std::process::exit(2);
    }
    if args.len() == 2 {
        eprintln!("error: The following required arguments were not provided:");
        eprintln!("    <vault name>");
        eprintln!();
        eprintln!("USAGE:");
        eprintln!("    executable vmove <item type> <name> <vault name>");
        eprintln!();
        eprintln!("For more information try --help");
        std::process::exit(2);
    }
    if args[0] == "-h" || args[0] == "--help" {
        help_vmove();
        return;
    }
    if args.len() > 3 {
        eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context", args[3]);
        eprintln!();
        eprintln!("USAGE:");
        eprintln!("    executable vmove <item type> <name> <vault name>");
        eprintln!();
        eprintln!("For more information try --help");
        std::process::exit(2);
    }
    let itype = args[0].to_lowercase();
    let name = args[1].clone();
    let dest_vault_name = args[2].clone();
    let is_note = match itype.as_str() {
        "note" | "nt" => true,
        "folder" | "fd" => false,
        _ => {
            eprintln!("error: \"{}\" isn't a valid value for '<item type>'", args[0]);
            eprintln!("\t[possible values: note, nt, folder, fd]");
            eprintln!();
            eprintln!("For more information try --help");
            std::process::exit(2);
        }
    };
    let cur_info = ensure_inside_vault();
    if cur_info.is_none() { return; }
    let (src_vname, src_vloc, current_folder, full_current) = cur_info.unwrap();
    let vaults = load_vaults();
    if !vaults.vaults.contains_key(&dest_vault_name) {
        error_print(&format!("vault {} doesn't exist", dest_vault_name));
        return;
    }
    let dest_vloc = vaults.vaults.get(&dest_vault_name).unwrap().clone();
    let source_path = if is_note {
        full_current.join(&name).with_extension("md")
    } else {
        full_current.join(&name)
    };
    if !source_path.exists() {
        error_print(&format!("no such file or directory (os error 2)"));
        return;
    }
    if src_vname == dest_vault_name {
        if is_note {
            print!("note {} already exists in vault {}", name, dest_vault_name);
        } else {
            print!("folder {} already exists in vault {}", name, dest_vault_name);
        }
        println!("{}: {}", "error".red(), "new location is same as old location");
        return;
    }
    let dest_vault_root = vault_root_path(&dest_vloc, &dest_vault_name);
    let dest_path = if is_note {
        dest_vault_root.join(&name).with_extension("md")
    } else {
        dest_vault_root.join(&name)
    };
    if dest_path.exists() {
        error_print(&format!("a {} named {} already exists in this location", if is_note { "note" } else { "folder" }, name));
        return;
    }
    if let Err(_) = fs::rename(&source_path, &dest_path) {
        error_print(&format!("no such file or directory (os error 2)"));
        return;
    }
    if !is_note {
        let source_rel = if current_folder.is_empty() { name.clone() } else { format!("{}/{}", current_folder, name) };
        if current_folder == source_rel || current_folder.starts_with(&format!("{}/", source_rel)) {
            write_data_file(&src_vloc, &src_vname, "");
        }
    }
    if is_note {
        println!("note {} moved to vault {}", colored_name(&name), colored_name(&dest_vault_name));
    } else {
        println!("folder {} moved to vault {}", colored_name(&name), colored_name(&dest_vault_name));
    }
}

fn cmd_config(args: &[String]) {
    if !args.is_empty() && (args[0] == "-h" || args[0] == "--help") {
        help_config();
        return;
    }
    let cfg = load_config();
    if args.is_empty() {
        let config_path = config_dir().join("config");
        let mut cmd = std::process::Command::new(&cfg.editor);
        cmd.arg(&config_path);
        match cmd.status() {
            Ok(_) => {},
            Err(e) => {
                if e.kind() == std::io::ErrorKind::NotFound {
                    error_print("editor not found");
                } else {
                    error_print(&format!("undefined error: {} (os error {})", e, e.raw_os_error().unwrap_or(0)));
                }
            }
        }
        return;
    }
    if args.len() == 1 {
        let ctype = args[0].to_lowercase();
        match ctype.as_str() {
            "editor" => {
                println!("editor: {}", cfg.editor.blue());
            },
            "conflict" => {
                println!("conflict: {}", format!("{}", cfg.conflict).blue());
            },
            _ => {
                eprintln!("error: \"{}\" isn't a valid value for '<config type>'", args[0]);
                eprintln!("\t[possible values: editor, conflict]");
                eprintln!();
                eprintln!("For more information try --help");
                std::process::exit(2);
            }
        }
        return;
    }
    if args.len() == 2 {
        let ctype = args[0].to_lowercase();
        let cvalue = args[1].clone();
        match ctype.as_str() {
            "editor" => {
                let new_cfg = AppConfig { editor: cvalue.clone(), conflict: cfg.conflict };
                save_config(&new_cfg);
                println!("set {} to {}", "editor".blue(), cvalue.blue());
            },
            "conflict" => {
                let bool_val = parse_bool(&cvalue);
                let new_cfg = AppConfig { editor: cfg.editor, conflict: bool_val };
                save_config(&new_cfg);
                println!("set {} to {}", "conflict".blue(), format!("{}", bool_val).blue());
            },
            _ => {
                eprintln!("error: \"{}\" isn't a valid value for '<config type>'", args[0]);
                eprintln!("\t[possible values: editor, conflict]");
                eprintln!();
                eprintln!("For more information try --help");
                std::process::exit(2);
            }
        }
        return;
    }
    eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context", args[2]);
    eprintln!();
    eprintln!("USAGE:");
    eprintln!("    jt config <config type>");
    eprintln!("    jt config <config type> [config value]");
    eprintln!();
    eprintln!("For more information try --help");
    std::process::exit(2);
}

