fn cmd_opdir(args: &[String]) {
    if !args.is_empty() {
        if args[0] == "-h" || args[0] == "--help" {
            help_opdir();
            return;
        }
        eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context", args[0]);
        eprintln!();
        eprintln!("USAGE:");
        eprintln!("    executable opdir");
        eprintln!();
        eprintln!("For more information try --help");
        std::process::exit(2);
    }
    let cur_info = ensure_inside_vault();
    if cur_info.is_none() { return; }
    let (_vname, _vloc, _folder, full_current) = cur_info.unwrap();
    let mut cmd = std::process::Command::new("xdg-open");
    cmd.arg(&full_current);
    match cmd.status() {
