fn cmd_vault(args: &[String]) {
    let mut l_flag = false;
    let mut vault_name: Option<String> = None;
    let mut vault_location: Option<String> = None;
    for a in args {
        if a == "-l" {
            l_flag = true;
        } else if a == "-h" || a == "--help" {
            help_vault();
            return;
        } else if vault_name.is_none() {
            vault_name = Some(a.clone());
        } else if vault_location.is_none() {
            vault_location = Some(a.clone());
        } else {
            eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context", a);
            eprintln!();
            eprintln!("USAGE:");
            eprintln!("    jt vault");
            eprintln!("    jt vault -l");
            eprintln!("    jt vault <vault name> <vault location>");
            eprintln!();
            eprintln!("For more information try --help");
            std::process::exit(2);
        }
    }
    if l_flag {
        let vaults = load_vaults();
        for (name, loc) in &vaults.vaults {
            if Some(name) == vaults.current.as_ref() {
                println!("👉 {} \t {}", colored_name(name), loc);
            } else {
                println!("   {} \t {}", name, loc);
            }
        }
        return;
    }
    if vault_name.is_none() {
        let vaults = load_vaults();
        for (name, _) in &vaults.vaults {
            if Some(name) == vaults.current.as_ref() {
                println!("👉 {}", colored_name(name));
            } else {
                println!("   {}", name);
            }
        }
        return;
    }
    let vault_name = vault_name.unwrap();
    if vault_location.is_none() {
        eprintln!("error: The following required arguments were not provided:");
        eprintln!("    <vault location>");
        eprintln!();
        eprintln!("USAGE:");
        eprintln!("    jt vault");
        eprintln!("    jt vault -l");
        eprintln!("    jt vault <vault name> <vault location>");
        eprintln!();
        eprintln!("For more information try --help");
        std::process::exit(2);
    }
    let vault_location = vault_location.unwrap();
    if is_invalid_name(&vault_name) {
        invalid_name_error();
        return;
    }
    if !Path::new(&vault_location).is_absolute() {
        error_print("specified path isn't absolute");
        return;
    }
    if !Path::new(&vault_location).exists() {
        error_print("couldn't find the path specified");
        return;
    }
    let mut vaults = load_vaults();
    if vaults.vaults.contains_key(&vault_name) {
        error_print(&format!("vault {} already exists", vault_name));
        return;
    }
    let full_path = vault_full_path(&vault_location, &vault_name);
    if full_path.exists() {
        error_print(&format!("a folder named {} already exists in this location", vault_name));
        return;
    }
    let _ = fs::create_dir_all(&full_path);
    let jot_dir = full_path.join(".jot");
    let _ = fs::create_dir_all(&jot_dir);
    write_data_file(&vault_location, &vault_name, "");
    vaults.vaults.insert(vault_name.clone(), vault_location);
    save_vaults(&vaults);
    println!("vault {} created", colored_name(&vault_name));
}

