fn resolve_chdir_target(current_folder: &str, target: &str, vault_location: &str, vault_name: &str) -> Result<String, String> {
    let vault_root = vault_root_path(vault_location, vault_name);
    if target.starts_with('/') {
        let target_path = Path::new(target);
        let mut stack: Vec<String> = Vec::new();
        for comp in target_path.components() {
            use std::path::Component;
            match comp {
                Component::RootDir => { stack.clear(); },
                Component::CurDir => {},
                Component::ParentDir => {
                    if !stack.is_empty() { stack.pop(); }
                },
                Component::Normal(os) => { stack.push(os.to_string_lossy().to_string()); },
                _ => {}
            }
        }
        let mut normalized = PathBuf::from("/");
        for s in &stack { normalized.push(s); }
        let inside = normalized == vault_root || normalized.starts_with(&vault_root);
        if !inside {
            if normalized.exists() {
                return Err("path crosses the bounds of vault".to_string());
            } else {
                return Err("couldn't find the path specified".to_string());
            }
        } else {
            let rel = if normalized == vault_root {
                "".to_string()
            } else {
                let rel_path = normalized.strip_prefix(&vault_root).unwrap();
                rel_path.to_string_lossy().to_string()
            };
            if !rel.is_empty() {
                let full = vault_root.join(&rel);
                if !full.is_dir() {
                    return Err("couldn't find the path specified".to_string());
                }
            }
            if rel == current_folder {
                return Err("new location is same as old location".to_string());
            }
            return Ok(rel);
        }
    } else {
        let cur_comps: Vec<String> = if current_folder.is_empty() { vec![] } else { current_folder.split('/').map(|s| s.to_string()).collect() };
        let mut stack = cur_comps.clone();
        let comps: Vec<String> = target.split('/').map(|s| s.to_string()).collect();
        let vault_root_pathbuf = Path::new(vault_location).join(vault_name);
        for idx in 0..comps.len() {
            let comp = &comps[idx];
            if comp.is_empty() { continue; }
            if comp == "." { continue; }
            if comp == ".." {
                if !stack.is_empty() {
                    stack.pop();
                } else {
                    let remaining = &comps[idx+1..];
                    let has_normal = remaining.iter().any(|c| !c.is_empty() && c != "." && c != "..");
                    if has_normal {
                        return Err("couldn't find the path specified".to_string());
                    } else {
                        return Err("path crosses the bounds of vault".to_string());
                    }
                }
            } else {
                let mut candidate_path = vault_root_pathbuf.clone();
                for s in &stack { candidate_path = candidate_path.join(s); }
                candidate_path = candidate_path.join(comp);
                if !candidate_path.is_dir() {
                    return Err("couldn't find the path specified".to_string());
                }
                stack.push(comp.clone());
            }
        }
        let final_rel = stack.join("/");
        if final_rel == current_folder {
            return Err("new location is same as old location".to_string());
        }
        Ok(final_rel)
    }
}

