fn cmd_list(args: &[String]) {
    if !args.is_empty() && (args[0] == "-h" || args[0] == "--help") {
        help_list();
        return;
    }
    let filter_opt = if args.is_empty() { None } else { Some(args[0].clone()) };
    if let Some(ref t) = filter_opt {
        match t.as_str() {
            "note" | "nt" | "folder" | "fd" => {},
            _ => {
                eprintln!("error: \"{}\" isn't a valid value for '<item type>'", t);
                eprintln!("\t[possible values: note, nt, folder, fd]");
                eprintln!();
                eprintln!("For more information try --help");
                std::process::exit(2);
            }
        }
    }
    let cur_info = ensure_inside_vault();
    if cur_info.is_none() { return; }
    let (vname, _vloc, folder, full_current) = cur_info.unwrap();
    let header = if folder.is_empty() { vname.clone() } else { format!("{} > {}", vname, folder) };
    println!("{}", header);

    if filter_opt.is_none() {
        fn collect_entries(path: &Path) -> Vec<(String, bool, PathBuf)> {
            let mut entries = Vec::new();
            if let Ok(read_dir) = fs::read_dir(path) {
                for entry in read_dir {
                    if let Ok(entry) = entry {
                        let ft = match entry.file_type() {
                            Ok(ft) => ft,
                            Err(_) => continue,
                        };
                        let fname = entry.file_name().to_string_lossy().to_string();
                        if fname == ".jot" { continue; }
                        let p = entry.path();
                        if ft.is_dir() {
                            entries.push((fname, false, p));
                        } else if ft.is_file() {
                            if p.extension().map_or(false, |ext| ext == "md") {
                                if let Some(stem) = p.file_stem() {
                                    entries.push((stem.to_string_lossy().to_string(), true, p));
                                }
                            }
                        }
                    }
                }
            }
            entries
        }
        fn print_recursive(path: &Path, is_last_stack: Vec<bool>) {
            let entries = collect_entries(path);
            let len = entries.len();
            for (i, (name, is_note, child_path)) in entries.into_iter().enumerate() {
                let is_last = i == len - 1;
                let mut line_prefix = String::new();
                for &is_last_parent in &is_last_stack {
                    if is_last_parent {
                        line_prefix.push_str("    ");
                    } else {
                        line_prefix.push_str("│   ");
                    }
                }
                let branch = if is_last { "└── " } else { "├── " };
                let display_name = if is_note { format!("{}{}{}", BLUE, name, RESET) } else { name.clone() };
                println!("{}{}{}", line_prefix, branch, display_name);
                if !is_note {
                    let mut new_stack = is_last_stack.clone();
                    new_stack.push(is_last);
                    print_recursive(&child_path, new_stack);
                }
            }
        }
        print_recursive(&full_current, vec![]);
    } else {
        let filter = filter_opt.unwrap();
        match filter.as_str() {
            "note" | "nt" => {
                if let Ok(read_dir) = fs::read_dir(&full_current) {
                    let mut notes = Vec::new();
                    for entry in read_dir {
                        if let Ok(entry) = entry {
                            let ft = match entry.file_type() {
                                Ok(ft) => ft,
                                Err(_) => continue,
                            };
                            if ft.is_file() {
                                let p = entry.path();
                                if p.extension().map_or(false, |ext| ext == "md") {
                                    if let Some(stem) = p.file_stem() {
                                        notes.push(stem.to_string_lossy().to_string());
                                    }
                                }
                            }
                        }
                    }
                    let len = notes.len();
                    for (i, name) in notes.iter().enumerate() {
                        let branch = if i == len - 1 { "└── " } else { "├── " };
                        println!("{}{}", branch, format!("{}{}{}", BLUE, name, RESET));
                    }
                }
            },
            "folder" | "fd" => {
                if let Ok(read_dir) = fs::read_dir(&full_current) {
                    let mut folders = Vec::new();
                    for entry in read_dir {
                        if let Ok(entry) = entry {
                            let ft = match entry.file_type() {
                                Ok(ft) => ft,
                                Err(_) => continue,
                            };
                            if ft.is_dir() {
                                folders.push(entry.file_name().to_string_lossy().to_string());
                            }
                        }
                    }
                    let len = folders.len();
                    for (i, name) in folders.iter().enumerate() {
                        let branch = if i == len - 1 { "└── " } else { "├── " };
                        println!("{}{}", branch, name);
                    }
                }
            },
            _ => {}
        }
    }
}

