        eprintln!("    executable rename <item type> <name> <new name>");
        eprintln!();
        eprintln!("For more information try --help");
        std::process::exit(2);
    }
    let itype = args[0].to_lowercase();
    let name = args[1].clone();
    let new_name = args[2].clone();
    if name == new_name {
        error_print("new name is same as old name");
        return;
    }
    if is_invalid_name(&new_name) {
        invalid_name_error();
        return;
    }
    match itype.as_str() {
        "vault" | "vl" => {
            let mut vaults = load_vaults();
            if !vaults.vaults.contains_key(&name) {
                error_print(&format!("vault {} doesn't exist", name));
                return;
            }
            if vaults.vaults.contains_key(&new_name) {
                error_print(&format!("vault {} already exists", new_name));
                return;
            }
            let loc = vaults.vaults.get(&name).unwrap().clone();
            let old_full = vault_full_path(&loc, &name);
            let new_full = vault_full_path(&loc, &new_name);
            if let Err(e) = fs::rename(&old_full, &new_full) {
                error_print(&format!("undefined error: {} (os error {})", e, e.raw_os_error().unwrap_or(0)));
                return;
            }
            let data_path = new_full.join(".jot").join("data");
            if data_path.exists() {
                if let Ok(content) = fs::read_to_string(&data_path) {
                    let mut new_content = String::new();
                    for line in content.lines() {
                        if line.trim_start().starts_with("name") {
                            new_content.push_str(&format!("name = '{}'\n", new_name));
                        } else {
                            new_content.push_str(line);
                            new_content.push('\n');
                        }
                    }
                    let _ = fs::write(&data_path, new_content);
                }
            } else {
                write_data_file(&loc, &new_name, "");
            }
            vaults.vaults.remove(&name);
            vaults.vaults.insert(new_name.clone(), loc);
            if let Some(cur) = &vaults.current {
                if cur == &name {
                    vaults.current = Some(new_name.clone());
                }
            }
            save_vaults(&vaults);
            println!("vault {} renamed to {}", blue_name(&name), blue_name(&new_name));
        },
        "note" | "nt" => {
            let cur_info = ensure_inside_vault();
            if cur_info.is_none() { return; }
            let (_vname, _vloc, _folder, full_current) = cur_info.unwrap();
            let note_path = full_current.join(&name).with_extension("md");
            if !note_path.exists() || !note_path.is_file() {
                error_print(&format!("note {} not found", name));
                return;
