        println!("folder {} moved to vault {}", blue_name(&name), blue_name(&dest_vault_name));
    }
}

fn cmd_config(args: &[String]) {
    if !args.is_empty() && (args[0] == "-h" || args[0] == "--help") {
        help_config();
        return;
    }
    let cfg = load_config();
    if args.is_empty() {
        let config_path = config_dir();
        let config_path = config_path.join("config");
        let mut cmd = std::process::Command::new(&cfg.editor);
        cmd.arg(&config_path);
        match cmd.status() {
            Ok(_) => {},
            Err(e) => {
                if e.kind() == std::io::ErrorKind::NotFound {
                    error_print("editor not found");
                } else {
                    error_print(&format!("undefined error: {} (os error {})", e, e.raw_os_error().unwrap_or(0)));
                }
            }
        }
        return;
    }
    if args.len() == 1 {
        let ctype = args[0].to_lowercase();
        match ctype.as_str() {
            "editor" => {
                println!("editor: {}", blue_name(&cfg.editor));
            },
            "conflict" => {
                println!("conflict: {}", blue_name(&format!("{}", cfg.conflict)));
            },
            _ => {
                eprintln!("error: \"{}\" isn't a valid value for '<config type>'", args[0]);
                eprintln!("\t[possible values: editor, conflict]");
                eprintln!();
                eprintln!("For more information try --help");
                std::process::exit(2);
            }
        }
        return;
    }
    if args.len() == 2 {
        let ctype = args[0].to_lowercase();
        let cvalue = args[1].clone();
        match ctype.as_str() {
            "editor" => {
                let new_cfg = AppConfig { editor: cvalue.clone(), conflict: cfg.conflict };
                save_config(&new_cfg);
                println!("set {} to {}", blue_name("editor"), blue_name(&cvalue));
            },
            "conflict" => {
                let bool_val = parse_bool(&cvalue);
                let new_cfg = AppConfig { editor: cfg.editor, conflict: bool_val };
                save_config(&new_cfg);
                println!("set {} to {}", blue_name("conflict"), blue_name(&format!("{}", bool_val)));
            },
            _ => {
                eprintln!("error: \"{}\" isn't a valid value for '<config type>'", args[0]);
                eprintln!("\t[possible values: editor, conflict]");
                eprintln!();
                eprintln!("For more information try --help");
                std::process::exit(2);
            }
        }
        return;
    }
    eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context", args[2]);
    eprintln!();
    eprintln!("USAGE:");
    eprintln!("    jt config <config type>");
    eprintln!("    jt config <config type> [config value]");
    eprintln!();
    eprintln!("For more information try --help");
    std::process::exit(2);
}

fn config_dir() -> PathBuf {
    if let Ok(x) = std::env::var("XDG_CONFIG_HOME") {
        PathBuf::from(x).join("jot")
    } else {
        dirs::config_dir().unwrap_or_else(|| PathBuf::from(std::env::var("HOME").unwrap()).join(".config")).join("jot")
    }
}
fn data_dir() -> PathBuf {
    if let Ok(x) = std::env::var("XDG_DATA_HOME") {
        PathBuf::from(x).join("jot")
    } else {
        dirs::data_dir().unwrap_or_else(|| PathBuf::from(std::env::var("HOME").unwrap()).join(".local").join("share")).join("jot")
    }
}

