fn is_invalid_name(name: &str) -> bool {
    if name.is_empty() { return true; }
    if name.contains('/') || name.contains('\\') {
        return true;
    }
    for c in ['?', '*', ':', '<', '>', '"', '|'] {
        if name.contains(c) {
            return true;
        }
    }
    false
}

fn cmd_vault(args: &[String]) {
    let mut l_flag = false;
