            return;
        }
        eprintln!("error: The following required arguments were not provided:");
        eprintln!("    <name>");
        eprintln!();
        eprintln!("USAGE:");
        eprintln!("    executable remove <item type> <name>");
        eprintln!();
        eprintln!("For more information try --help");
        std::process::exit(2);
    }
    if args[0] == "-h" || args[0] == "--help" {
        help_remove();
        return;
    }
    if args.len() > 2 {
        eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context", args[2]);
        eprintln!();
        eprintln!("USAGE:");
        eprintln!("    executable remove <item type> <name>");
        eprintln!();
        eprintln!("For more information try --help");
        std::process::exit(2);
    }
    let itype = args[0].to_lowercase();
    let name = args[1].clone();
    match itype.as_str() {
        "vault" | "vl" => {
            let mut vaults = load_vaults();
            if !vaults.vaults.contains_key(&name) {
                error_print(&format!("vault {} doesn't exist", name));
                return;
            }
            let loc = vaults.vaults.get(&name).unwrap().clone();
            let full_path = vault_full_path(&loc, &name);
            if full_path.exists() {
                let _ = fs::remove_dir_all(&full_path);
            }
            vaults.vaults.remove(&name);
            if let Some(cur) = &vaults.current {
                if cur == &name {
                    vaults.current = None;
                }
            }
            save_vaults(&vaults);
            println!("vault {} removed", blue_name(&name));
        },
        "note" | "nt" => {
            let cur_info = ensure_inside_vault();
            if cur_info.is_none() { return; }
            let (_vname, _vloc, _folder, full_current) = cur_info.unwrap();
            let note_path = full_current.join(&name).with_extension("md");
            if !note_path.exists() || !note_path.is_file() {
                error_print(&format!("note {} not found", name));
                return;
            }
            let _ = fs::remove_file(&note_path);
            println!("note {} removed", blue_name(&name));
        },
        "folder" | "fd" => {
            let cur_info = ensure_inside_vault();
            if cur_info.is_none() { return; }
            let (vname, vloc, current_folder, full_current) = cur_info.unwrap();
            let folder_path = full_current.join(&name);
            if !folder_path.exists() || !folder_path.is_dir() {
                error_print(&format!("folder {} not found", name));
                return;
            }
            let removed_rel = if current_folder.is_empty() { name.clone() } else { format!("{}/{}", current_folder, name) };
            let _ = fs::remove_dir_all(&folder_path);
            if current_folder == removed_rel || current_folder.starts_with(&format!("{}/", removed_rel)) {
                write_data_file(&vloc, &vname, "");
            }
            println!("folder {} removed", blue_name(&name));
        },
        _ => {
            eprintln!("error: \"{}\" isn't a valid value for '<item type>'", args[0]);
            eprintln!("\t[possible values: note, nt, folder, fd, vault, vl]");
            eprintln!();
            eprintln!("For more information try --help");
            std::process::exit(2);
        }
    }
}

fn cmd_rename(args: &[String]) {
    if args.is_empty() {
        eprintln!("error: The following required arguments were not provided:");
        eprintln!("    <item type>");
        eprintln!("    <name>");
        eprintln!("    <new name>");
        eprintln!();
        eprintln!("USAGE:");
        eprintln!("    executable rename <item type> <name> <new name>");
        eprintln!();
        eprintln!("For more information try --help");
        std::process::exit(2);
    }
    if args.len() == 1 {
        eprintln!("error: The following required arguments were not provided:");
        eprintln!("    <name>");
        eprintln!("    <new name>");
        eprintln!();
        eprintln!("USAGE:");
        eprintln!("    executable rename <item type> <name> <new name>");
        eprintln!();
        eprintln!("For more information try --help");
        std::process::exit(2);
    }
    if args.len() == 2 {
        eprintln!("error: The following required arguments were not provided:");
        eprintln!("    <new name>");
        eprintln!();
        eprintln!("USAGE:");
        eprintln!("    executable rename <item type> <name> <new name>");
        eprintln!();
        eprintln!("For more information try --help");
        std::process::exit(2);
    }
    if args[0] == "-h" || args[0] == "--help" {
        help_rename();
        return;
    }
    if args.len() > 3 {
        eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context", args[3]);
        eprintln!();
        eprintln!("USAGE:");
        eprintln!("    executable rename <item type> <name> <new name>");
        eprintln!();
        eprintln!("For more information try --help");
        std::process::exit(2);
    }
    let itype = args[0].to_lowercase();
    let name = args[1].clone();
    let new_name = args[2].clone();
    if name == new_name {
        error_print("new name is same as old name");
        return;
    }
    if is_invalid_name(&new_name) {
        error_print("invalid name");
        return;
    }
    match itype.as_str() {
        "vault" | "vl" => {
            let mut vaults = load_vaults();
            if !vaults.vaults.contains_key(&name) {
                error_print(&format!("vault {} doesn't exist", name));
                return;
            }
            if vaults.vaults.contains_key(&new_name) {
                error_print(&format!("vault {} already exists", new_name));
                return;
            }
            let loc = vaults.vaults.get(&name).unwrap().clone();
            let old_full = vault_full_path(&loc, &name);
            let new_full = vault_full_path(&loc, &new_name);
            if let Err(e) = fs::rename(&old_full, &new_full) {
                error_print(&format!("undefined error: {} (os error {})", e, e.raw_os_error().unwrap_or(0)));
                return;
            }
            let data_path = new_full.join(".jot").join("data");
            if data_path.exists() {
                if let Ok(content) = fs::read_to_string(&data_path) {
                    let mut new_content = String::new();
                    for line in content.lines() {
                        if line.trim_start().starts_with("name") {
                            new_content.push_str(&format!("name = '{}'\n", new_name));
                        } else {
                            new_content.push_str(line);
                            new_content.push('\n');
                        }
                    }
                    let _ = fs::write(&data_path, new_content);
                }
            } else {
                write_data_file(&loc, &new_name, "");
            }
            vaults.vaults.remove(&name);
            vaults.vaults.insert(new_name.clone(), loc);
            if let Some(cur) = &vaults.current {
                if cur == &name {
                    vaults.current = Some(new_name.clone());
                }
            }
            save_vaults(&vaults);
            println!("vault {} renamed to {}", blue_name(&name), blue_name(&new_name));
        },
        "note" | "nt" => {
            let cur_info = ensure_inside_vault();
            if cur_info.is_none() { return; }
            let (_vname, _vloc, _folder, full_current) = cur_info.unwrap();
            let note_path = full_current.join(&name).with_extension("md");
            if !note_path.exists() || !note_path.is_file() {
                error_print(&format!("note {} not found", name));
                return;
            }
            let new_note_path = full_current.join(&new_name).with_extension("md");
            match fs::rename(&note_path, &new_note_path) {
                Ok(_) => {
                    println!("note {} renamed to {}", blue_name(&name), blue_name(&new_name));
                },
                Err(e) => {
                    error_print(&format!("undefined error: {} (os error {})", e, e.raw_os_error().unwrap_or(0)));
                }
            }
        },
        "folder" | "fd" => {
            let cur_info = ensure_inside_vault();
            if cur_info.is_none() { return; }
            let (_vname, _vloc, _folder, full_current) = cur_info.unwrap();
            let folder_path = full_current.join(&name);
            if !folder_path.exists() || !folder_path.is_dir() {
                error_print(&format!("folder {} not found", name));
                return;
            }
            let new_folder_path = full_current.join(&new_name);
            if new_folder_path.exists() {
                error_print(&format!("undefined error: File exists (os error 17)"));
                return;
            }
            match fs::rename(&folder_path, &new_folder_path) {
                Ok(_) => {
                    println!("folder {} renamed to {}", blue_name(&name), blue_name(&new_name));
                },
                Err(e) => {
                    error_print(&format!("undefined error: {} (os error {})", e, e.raw_os_error().unwrap_or(0)));
                }
            }
        },
        _ => {
            eprintln!("error: \"{}\" isn't a valid value for '<item type>'", args[0]);
            eprintln!("\t[possible values: note, nt, folder, fd, vault, vl]");
            eprintln!();
            eprintln!("For more information try --help");
            std::process::exit(2);
        }
    }
}

fn cmd_move(args: &[String]) {
    if args.is_empty() {
        eprintln!("error: The following required arguments were not provided:");
        eprintln!("    <item type>");
        eprintln!("    <name>");
        eprintln!("    <new location>");
        eprintln!();
        eprintln!("USAGE:");
        eprintln!("    executable move <item type> <name> <new location>");
        eprintln!();
        eprintln!("For more information try --help");
        std::process::exit(2);
    }
    if args.len() == 1 {
        eprintln!("error: The following required arguments were not provided:");
        eprintln!("    <name>");
        eprintln!("    <new location>");
        eprintln!();
        eprintln!("USAGE:");
        eprintln!("    executable move <item type> <name> <new location>");
        eprintln!();
        eprintln!("For more information try --help");
        std::process::exit(2);
    }
    if args.len() == 2 {
        eprintln!("error: The following required arguments were not provided:");
        eprintln!("    <new location>");
        eprintln!();
        eprintln!("USAGE:");
        eprintln!("    executable move <item type> <name> <new location>");
        eprintln!();
        eprintln!("For more information try --help");
        std::process::exit(2);
    }
    if args[0] == "-h" || args[0] == "--help" {
        help_move();
        return;
    }
    if args.len() > 3 {
        eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context", args[3]);
        eprintln!();
        eprintln!("USAGE:");
        eprintln!("    executable move <item type> <name> <new location>");
        eprintln!();
        eprintln!("For more information try --help");
        std::process::exit(2);
    }
    let itype = args[0].to_lowercase();
    let name = args[1].clone();
    let new_location = args[2].clone();
    match itype.as_str() {
        "vault" | "vl" => {
            let mut vaults = load_vaults();
            if !vaults.vaults.contains_key(&name) {
                error_print(&format!("vault {} doesn't exist", name));
                return;
            }
            if !Path::new(&new_location).is_absolute() {
                error_print("specified path isn't absolute");
                return;
            }
            if !Path::new(&new_location).exists() {
                error_print(&format!("no such file or directory (os error 2)"));
                return;
            }
            let old_loc = vaults.vaults.get(&name).unwrap().clone();
            if old_loc == new_location {
                error_print("new location is same as old location");
                return;
            }
            let old_full = vault_full_path(&old_loc, &name);
            let new_full = vault_full_path(&new_location, &name);
            if new_full.exists() {
                error_print(&format!("a folder named {} already exists in this location", name));
                return;
            }
            if let Err(_e) = fs::rename(&old_full, &new_full) {
                error_print(&format!("no such file or directory (os error 2)"));
                return;
            }
            let data_path = new_full.join(".jot").join("data");
            if data_path.exists() {
                if let Ok(content) = fs::read_to_string(&data_path) {
                    let mut new_content = String::new();
                    for line in content.lines() {
                        if line.trim_start().starts_with("location") {
                            new_content.push_str(&format!("location = '{}'\n", new_location));
                        } else {
                            new_content.push_str(line);
                            new_content.push('\n');
                        }
                    }
                    let _ = fs::write(&data_path, new_content);
                }
            }
            vaults.vaults.insert(name.clone(), new_location);
            save_vaults(&vaults);
            println!("vault {} moved", blue_name(&name));
        },
        "note" | "nt" | "folder" | "fd" => {
            let is_note = matches!(itype.as_str(), "note" | "nt");
            let cur_info = ensure_inside_vault();
            if cur_info.is_none() { return; }
            let (vname, vloc, current_folder, full_current) = cur_info.unwrap();
            let vault_root = vault_root_path(&vloc, &vname);
            let source_path = if is_note {
                full_current.join(&name).with_extension("md")
            } else {
                full_current.join(&name)
            };
            if !source_path.exists() {
                if is_note {
                    error_print(&format!("note {} not found", name));
                } else {
                    error_print(&format!("folder {} not found", name));
                }
                return;
            }
            if is_note && !source_path.is_file() {
                error_print(&format!("note {} not found", name));
                return;
            }
            if !is_note && !source_path.is_dir() {
                error_print(&format!("folder {} not found", name));
                return;
            }
            let dest_folder_rel = match resolve_chdir_target(&current_folder, &new_location, &vloc, &vname) {
                Ok(rel) => rel,
                Err(msg) => {
                    error_print(&msg);
                    return;
                }
            };
            let dest_full = if dest_folder_rel.is_empty() { vault_root.clone() } else { vault_root.join(&dest_folder_rel) };
            let final_dest = if is_note {
                dest_full.join(&name).with_extension("md")
            } else {
                dest_full.join(&name)
            };
            if !is_note && final_dest.starts_with(&source_path) {
                let _ = fs::remove_dir_all(&source_path);
                let source_rel = if current_folder.is_empty() { name.clone() } else { format!("{}/{}", current_folder, name) };
                if current_folder == source_rel || current_folder.starts_with(&format!("{}/", source_rel)) {
                    write_data_file(&vloc, &vname, "");
                }
                println!("folder {} moved", blue_name(&name));
                return;
            }
            if final_dest.exists() {
                if is_note {
                    error_print(&format!("a note named {} already exists in this location", name));
                } else {
                    error_print(&format!("a folder named {} already exists in this location", name));
                }
                return;
            }
            if is_note {
                if let Err(e) = fs::rename(&source_path, &final_dest) {
                    error_print(&format!("{} (os error {})", e, e.raw_os_error().unwrap_or(0)));
                    return;
                }
                println!("note {} moved", blue_name(&name));
            } else {
                let source_rel = if current_folder.is_empty() { name.clone() } else { format!("{}/{}", current_folder, name) };
                if let Err(e) = fs::rename(&source_path, &final_dest) {
                    error_print(&format!("{} (os error {})", e, e.raw_os_error().unwrap_or(0)));
                    return;
                }
                if current_folder == source_rel || current_folder.starts_with(&format!("{}/", source_rel)) {
                    write_data_file(&vloc, &vname, "");
                }
                println!("folder {} moved", blue_name(&name));
            }
        },
        _ => {
            eprintln!("error: \"{}\" isn't a valid value for '<item type>'", args[0]);
            eprintln!("\t[possible values: note, nt, folder, fd, vault, vl]");
            eprintln!();
            eprintln!("For more information try --help");
            std::process::exit(2);
        }
    }
}

fn cmd_vmove(args: &[String]) {
    if args.is_empty() {
        eprintln!("error: The following required arguments were not provided:");
        eprintln!("    <item type>");
        eprintln!("    <name>");
        eprintln!("    <vault name>");
        eprintln!();
        eprintln!("USAGE:");
